ZAKLJUCI.ONLOAD:
if (@@id=0) raiserror ('Niste odabrali dokument', 16, 1)
else if (select Status from PrnRadniNalog where PrnRadniNalogId=@@id) = 0 raiserror ('Radni nalog mora biti lansiran da bi se mogao zaključiti!', 16, 1)
else if (select Status from PrnRadniNalog where PrnRadniNalogId=@@id) = 2 raiserror ('Radni nalog je već zaključen.', 16, 1)
